import frappe

def send_committee_notification(doc, method):
    if doc.user:
        user_email = frappe.db.get_value("User", doc.user, "email")
        committee_name = frappe.db.get_value("Committee", doc.parent, "committee_name")

        if user_email and committee_name:
            frappe.sendmail(
                recipients=[user_email],
                subject="Committee Membership",
                message=f"आपको कमेटी ({committee_name}) में जोड़ा गया है।"
            )

import frappe

def notify_chairman(user_doc):
    roles = [d.role for d in user_doc.roles]
    if "Chairman" in roles:
        subject = "You have been assigned as Chairman"
        message = f"Dear {user_doc.full_name or user_doc.first_name},\n\nYou have been assigned the role of 'Chairman'. Please login to your account to view details."

        if user_doc.email:
            frappe.sendmail(
                recipients=user_doc.email,
                subject=subject,
                message=message
            )

notify_chairman(doc)

