import frappe

@frappe.whitelist()
def check_existing_bid(material_request):
    """Check if a Bid Creation exists for a given Material Request"""
    if not material_request:
        return None

    bid_name = frappe.db.get_value("Bid Creation", {"material_request": material_request}, "name")
    return bid_name or None

import frappe

def after_save(doc, method=None):
    # Purane shares clean karo
    shares = frappe.get_all(
        "DocShare",
        filters={"share_doctype": doc.doctype, "share_name": doc.name},
        pluck="name"
    )
    for s in shares:
        frappe.delete_doc("DocShare", s, ignore_permissions=True)

    # Chairman ko share karo
    if doc.get("committee_member_table"):
        for row in doc.committee_member_table:
            if row.is_chairman:   # sirf agar chairman tick hai
                user = frappe.db.get_value("User", {"email": row.contact_email}, "name")
                if user:
                    frappe.share.add(
                        doc.doctype,
                        doc.name,
                        user,
                        read=1, write=0, submit=0, share=0, notify=1
                    )

import frappe
from frappe.model.document import Document
class CommitteeMember(Document):
    def validate(self):
        if self.is_chairman and "Managing Officer" not in frappe.get_roles(frappe.session.user):
            frappe.throw("Only Managing Officer can Chairman select")
